// ======================================================================
// StatePolicy trait implementation
// ======================================================================

impl StatePolicy for StaticOptionalUnwidenedPolicy {
    type State = StaticOptionalUnwidenedState;
    type Event = StaticOptionalUnwidenedEvent;
    // W3C SCXML 3.10: this document declares no <history>, so no target list
    // can name one.
    type History = sce_rust_runtime::NoHistory;
    // EventSchema native lowering: `()` = schemaless (dynamic
    // `_event.data` baseline); a `<Machine>Payload` sum is emitted when a
    // transition guard reads a typed `_event.data.<field>` (NL→IR C1 Path A).
    type Payload = ();
    type Hal = sce_rust_runtime::StdHal;

    // W3C SCXML Appendix D internalQueue / externalQueue. Under no_std the
    // depth is the per-document `<scxml sce:capacity>` / deploy value (emitted
    // as the const consumed below); absent a declared capacity the bare form
    // inherits the runtime default `MAX_EVENT_QUEUE_DEPTH` (the single source of
    // the default). Inert under std (`VecDeque`), so this one emission compiles
    // on both runtime profiles.
    type EventQueue = sce_rust_runtime::EventQueueManager<
        sce_rust_runtime::EventWithMetadata<Self::Event, Self::Payload>,
    >;

    // W3C SCXML 6.3: the delayed-send scheduler keeps a per-entry `send_id` only
    // so `<cancel sendid>` can find and drop the matching entry; the timer-fire
    // drain never reads it. A document with no `<cancel>` therefore emits the
    // zero-size `ElidedSendId`, shedding the scheduler ring's per-entry
    // `heapless::String<256>` (~256 B x MAX_SCHEDULED_EVENTS) under no_std --
    // dead weight with no cancel reader. A cancelling document keeps the
    // load-bearing `SceString`. Behaviour-preserving under std either way, so
    // this one emission compiles on both runtime profiles. Mirrors the
    // EventQueue per-machine sizing lever above.
    type ScheduledSendId = sce_rust_runtime::ElidedSendId;

    // W3C SCXML 3.4: what this document's state tree bounds, read by the
    // generator and written here so every buffer of the runtime's microstep is
    // this document's size and no larger. A configuration holds 1 state(s) at
    // most; a selection enables 1 transition(s) at most, one from each atomic state
    // of one; the deepest state sits 1 level(s) down. Under std the buffers
    // are `Vec`s and the capacities are not read.
    type Configuration = StaticOptionalUnwidenedConfiguration;
    type EnabledSet = ::sce_rust_runtime::helpers::hierarchy::BoundedVec<
        ::sce_rust_runtime::EnabledTransition<Self::State, Self::History>,
        1,
    >;
    type HistoryDefaults =
        ::sce_rust_runtime::helpers::hierarchy::BoundedVec<(Self::State, Self::History), 0>;
    // Appendix D's entry procedures, the effective targets and the completion
    // check are run over a stack of steps and not by recursion, so a call needs
    // no depth the program has to assume: 6 step(s) at most, three for each level
    // of the tree, one for each `<history>` and three of headroom.
    type EntryWalk = ::sce_rust_runtime::helpers::hierarchy::BoundedVec<
        ::sce_rust_runtime::helpers::microstep::WalkStep<Self::State, Self::History>,
        6,
    >;
    const MAX_CONFIGURATION: usize = 1;
    const MAX_ENABLED: usize = 1;
    const MAX_DEPTH: usize = 1;

    // W3C SCXML feature flags
    const HAS_PARALLEL_STATES: bool = false;
    const NEEDS_SCRIPT_ENGINE: bool = false;
    const NEEDS_DATA_MODEL_INIT: bool = false;
    // The same fact the generate manifest publishes as `needs_event_scheduler`.
    // A `build.rs` consumer never sees that manifest — `compile_scxml` returns
    // `()` — so without this constant a host had no route to the knowledge that
    // its driving loop must call `tick()` rather than `step()`.
    const NEEDS_EVENT_SCHEDULER: bool = false;
    // The generate manifest's `needs_parent`: what a root-start policy reads.
    const NEEDS_PARENT: bool = false;

    // ======================================================================
    // Static metadata methods (W3C SCXML document structure)
    // ======================================================================

    fn initial_state() -> Self::State {
        // The runtime entry state and the type's `Default` derive are one
        // concept, sourced from one computation (`default_state_id`) so
        // they can never diverge: `<scxml initial>`, or the first sorted
        // state when the initial attribute is unset.
        StaticOptionalUnwidenedState::Tracking
    }

    fn is_final_state(state: Self::State) -> bool {
        match state {
            StaticOptionalUnwidenedState::Done => true,
            _ => false,
        }
    }

    fn get_parent(state: Self::State) -> Option<Self::State> {
        match state {
            _ => None,
        }
    }

    // W3C SCXML 3.3: a <state> with child states — exactly the states that have
    // an initial transition. A <parallel> is not compound.
    fn is_compound_state(state: Self::State) -> bool {
        match state {
            _ => false,
        }
    }

    // §scxml-D-getChildStates: a state's <state>, <parallel> and <final>
    // children, in document order — for a <parallel>, its regions.
    fn get_child_states(state: Self::State) -> &'static [Self::State] {
        match state {
            _ => &[],
        }
    }

    // §scxml-3.3: a compound state's initial transition target, as written —
    // the engine's entry procedures dereference a <history> among them.
    fn get_initial_targets(
        state: Self::State,
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        match state {
            _ => &[],
        }
    }

    // §scxml-3.2: the target of the document's own initial transition, as written.
    fn get_document_initial_targets(
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        &[::sce_rust_runtime::EntryTarget::State(
            StaticOptionalUnwidenedState::Tracking,
        )]
    }

    // §scxml-3.10: the state a <history> is declared in.
    fn get_history_parent(history: Self::History) -> Self::State {
        match history {}
    }

    // §scxml-3.10.2: a <history>'s default transition target, as written.
    fn get_history_default_targets(
        history: Self::History,
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        match history {}
    }

    fn get_document_order(state: Self::State) -> u32 {
        match state {
            StaticOptionalUnwidenedState::Done => 1,
            StaticOptionalUnwidenedState::Tracking => 0,
        }
    }

    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            StaticOptionalUnwidenedEvent::Finish => "finish",
            StaticOptionalUnwidenedEvent::Keep => "keep",
            StaticOptionalUnwidenedEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "finish" => Some(StaticOptionalUnwidenedEvent::Finish),
            "keep" => Some(StaticOptionalUnwidenedEvent::Keep),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            StaticOptionalUnwidenedState::Done => "done",
            StaticOptionalUnwidenedState::Tracking => "tracking",
        }
    }

    // The inverse of the table above, emitted from the same loop over the
    // document's states so the two age together. It is what lets a host turn a
    // recorded configuration back into the slice `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "done" => Some(StaticOptionalUnwidenedState::Done),
            "tracking" => Some(StaticOptionalUnwidenedState::Tracking),
            _ => None,
        }
    }

    fn null_event() -> Self::Event {
        StaticOptionalUnwidenedEvent::Null
    }

    // ======================================================================
    // Run-time state the entry procedures read
    // ======================================================================

    // §scxml-3.10: what a <history> recorded when its parent was last exited;
    // None before that ever happened.
    fn history_value(&self, history: Self::History) -> Option<&[Self::State]> {
        match history {}
    }

    // ======================================================================
    // Instance methods - generated executable content
    // ======================================================================

    // W3C SCXML 3.7: Execute <onentry> actions for a state
    #[doc = "SCE-MAP: static_optional_unwidened.scxml:16 :: _machine"]
    // SCE-MAP: static_optional_unwidened.scxml:16 :: _machine
    fn execute_entry_actions(
        &mut self,
        state: Self::State,
        engine: &mut sce_rust_runtime::Engine<Self>,
        is_default_entry: bool,
    ) {
    }

    // §scxml-3.10.2: a <history>'s default transition content, run after its
    // parent's onentry (and after the parent's own <initial> content) when the
    // history was taken with nothing recorded. The engine asks for it by the
    // entry set's defaultHistoryContent answer; a history that restored what it
    // recorded runs nothing.

    // W3C SCXML 3.8: Execute <onexit> actions for a state
    #[doc = "SCE-MAP: static_optional_unwidened.scxml:16 :: _machine"]
    // SCE-MAP: static_optional_unwidened.scxml:16 :: _machine
    fn execute_exit_actions(
        &mut self,
        state: Self::State,
        engine: &mut sce_rust_runtime::Engine<Self>,
        configuration_before_exit: &[Self::State],
    ) {
        // §scxml-D-exitStates orders one state's exit as onexit, then
        // cancelInvoke, then configuration.delete(s), so `In(s)` inside s's
        // own handler is true: the deactivation is the LAST step here.
    }

    // Appendix D selectTransitions, the half only this document can answer:
    // the first of `state`'s own transitions, in document order, that `event`
    // enables. The engine walks the atomic states and their ancestors and
    // keeps the ordered set. `Event::Null` asks for eventless transitions.
    #[doc = "SCE-MAP: static_optional_unwidened.scxml:16 :: _machine"]
    // SCE-MAP: static_optional_unwidened.scxml:16 :: _machine
    fn first_enabled_transition(
        &mut self,
        state: Self::State,
        event: Self::Event,
        engine: &mut sce_rust_runtime::Engine<Self>,
    ) -> Option<::sce_rust_runtime::EnabledTransition<Self::State, Self::History>> {
        match state {
            StaticOptionalUnwidenedState::Tracking => {
                if event == StaticOptionalUnwidenedEvent::Keep {
                    {
                        return Some(::sce_rust_runtime::EnabledTransition {
                            source: state,
                            targets: &[],
                            transition_index: 0,
                            has_actions: true,
                            is_internal: true,
                        });
                    }
                }
                if event == StaticOptionalUnwidenedEvent::Finish {
                    {
                        return Some(::sce_rust_runtime::EnabledTransition {
                            source: state,
                            targets: &[::sce_rust_runtime::EntryTarget::State(
                                StaticOptionalUnwidenedState::Done,
                            )],
                            transition_index: 1,
                            has_actions: false,
                            is_internal: false,
                        });
                    }
                }
                None
            }
            _ => None,
        }
    }

    // W3C SCXML 3.13: a transition's executable content, run by the engine
    // between the microstep's exits and its entries.
    #[doc = "SCE-MAP: static_optional_unwidened.scxml:16 :: _machine"]
    // SCE-MAP: static_optional_unwidened.scxml:16 :: _machine
    fn execute_transition_content(
        &mut self,
        source: Self::State,
        transition_index: usize,
        engine: &mut sce_rust_runtime::Engine<Self>,
    ) {
        match source {
            StaticOptionalUnwidenedState::Tracking => {
                match transition_index {
                    0 => {
                        // SCE-MAP: static_optional_unwidened.scxml:52 :: tracking :: _transition_0
                        // W3C SCXML 3.13: Transition 0 actions
                        // W3C SCXML 4.9: a transition's content is one block; an error ends it.
                        'action_block: {
                            // SCE Accepted Subset §2.15: <sce:append target="items">
                            let sce_failed = if self.items.len() < 3 {
                                self.items.push(self.item.clone());
                                false
                            } else {
                                true
                            };
                            if sce_failed {
                                break 'action_block; // W3C SCXML 4.9: the error ends the block
                            }
                        }
                    }
                    _ => {}
                }
            }
            _ => {}
        }
    }

    // W3C SCXML 6.2 + 6.4: a delayed `<send target="#_parent">` whose wait is
    // over, with the payload an immediate one carries. It waited in this
    // machine's own queue, so `<cancel>` reached it and a child that ended
    // first dropped it — the engine dispatches nothing once final.
    fn deliver_to_parent(&mut self, event_name: &str, event_data: &str) -> bool {
        if let Some(ref parent_queue) = self.parent_external_queue {
            if let Ok(mut q) = parent_queue.lock() {
                q.push((event_name.to_string(), event_data.to_string()));
                return true;
            }
        }
        false
    }

    // W3C SCXML C.1: whether a session invoked this one — the queue the
    // invoking parent installs is the link to it.
    fn has_parent_session(&self) -> bool {
        self.parent_external_queue.is_some()
    }

    // docs/adr/0045: this session's own id, as a saved state holds it.
    fn own_session_id(&self) -> &str {
        self.session_id.as_deref().unwrap_or("")
    }

    // docs/adr/0045: a restored session carries on under its saved id.
    fn bind_session_id(&mut self, session_id: &str) {
        self.session_id = Some(session_id.to_string());
    }
}
